<?php

namespace Pharaonic\Laravel\Modulator\Tests\Feature;

use Pharaonic\Laravel\Modulator\Facades\Modules;
use Pharaonic\Laravel\Modulator\Tests\TestCase;

/**
 * A 1.x module (app/Modules/<Name>, generated by 1.x module:make) keeps working.
 */
class LegacyModuleTest extends TestCase
{
    protected function setUp(): void
    {
        parent::setUp();

        $this->autoloadApp();

        $this->write('app/Modules/ServiceProvider.php', <<<'PHP'
<?php

namespace App\Modules;

use Illuminate\Support\ServiceProvider as IlluminateServiceProvider;

// 1.x extended Pharaonic\Laravel\Modulator\Core\ServiceProvider: the upgrade changes this one line.
class ServiceProvider extends IlluminateServiceProvider
{
    public function register()
    {
    }

    public function boot()
    {
    }
}
PHP);
        $this->write('app/Modules/Forum/Providers/AppServiceProvider.php', <<<'PHP'
<?php

namespace App\Modules\Forum\Providers;

use App\Modules\ServiceProvider;

class AppServiceProvider extends ServiceProvider
{
    public static $module = "Forum";

    public function register()
    {
        $this->app->instance('forum.registered', module_path(static::$module, 'routes/web.php'));
    }

    public function boot()
    {
        parent::boot();
    }
}
PHP);
        $this->write('app/Modules/Forum/Providers/RouteServiceProvider.php', <<<'PHP'
<?php

namespace App\Modules\Forum\Providers;

use Illuminate\Support\Facades\Route;
use Illuminate\Support\ServiceProvider;

class RouteServiceProvider extends ServiceProvider
{
    public function boot()
    {
        Route::middleware('web')->prefix('forum')->name('forum.')->group(module_path(AppServiceProvider::$module, 'routes/web.php'));
    }
}
PHP);
        $this->write('app/Modules/Forum/routes/web.php', "<?php Route::get('/', function () { return 'forum home'; })->name('home');");
        $this->write('app/Modules/Forum/config/app.php', "<?php return ['title' => 'Forum'];");
        $this->write('app/Modules/Forum/lang/en/forum.php', "<?php return ['welcome' => 'Welcome to the forum'];");
        $this->write('app/Modules/Forum/resources/views/index.blade.php', 'forum view');
        $this->write('app/Modules/Forum/helpers.php', "<?php if (! function_exists('forum_helper')) { function forum_helper() { return 'helped'; } }");
        $this->write('app/Modules/Forum/Commands/Prune.php', <<<'PHP'
<?php

namespace App\Modules\Forum\Commands;

use Illuminate\Console\Command;

class Prune extends Command
{
    protected $signature = 'forum:prune';

    public function handle()
    {
        $this->info('pruned');

        return 0;
    }
}
PHP);

        $this->reload();
    }

    public function test_a_1x_module_keeps_its_namespace_providers_and_resources(): void
    {
        $forum = Modules::find('Forum');

        $this->assertSame('app', $forum->pool());
        $this->assertSame('App\\Modules\\Forum', $forum->namespace());
        $this->assertSame(realpath($this->base.'/app/Modules/Forum').DIRECTORY_SEPARATOR.'routes'.DIRECTORY_SEPARATOR.'web.php', $this->app->make('forum.registered'));
        $this->assertSame('Forum', config('modules.forum.app.title'));
        $this->assertSame('Welcome to the forum', trans('forum::forum.welcome'));
        $this->assertSame('forum view', view('forum::index')->render());
        $this->assertSame('helped', forum_helper());
        $this->get('forum')->assertOk()->assertSee('forum home');
        $this->artisan('forum:prune')->expectsOutput('pruned')->assertExitCode(0);
    }

    public function test_a_1x_module_can_be_disabled(): void
    {
        $this->reload(['disabled' => ['Forum']]);

        $this->assertFalse($this->app->bound('forum.registered'));
        $this->get('forum')->assertNotFound();
    }

    /**
     * Regression: 1.x loaded resources and replaced the factory resolver inside
     * the module provider constructor, before the provider was even registered.
     */
    public function test_constructing_a_legacy_module_provider_has_no_side_effects(): void
    {
        $before = count($this->app['view']->getFinder()->getHints());

        new \App\Modules\Forum\Providers\AppServiceProvider($this->app);

        $this->assertSame($before, count($this->app['view']->getFinder()->getHints()));
    }
}
